static void sphere_vertex(float lat, float lon, float radius) {
  float x = cosf(lat) * cosf(lon), y = cosf(lat) * sinf(lon), z = sinf(lat);
  glNormal3f(x, y, z);
  glVertex3f(radius * x, radius * y, radius * z);
}

static void build_sphere(GLuint list, int stacks, int slices, float radius) {
  glNewList(list, GL_COMPILE);
  glBegin(GL_TRIANGLES);
  for (int i = 0; i < stacks; i++) {
    float la0 = -PI / 2 + PI * i / stacks, la1 = -PI / 2 + PI * (i + 1) / stacks;
    for (int j = 0; j < slices; j++) {
      float lo0 = 2 * PI * j / slices, lo1 = 2 * PI * (j + 1) / slices;
      sphere_vertex(la0, lo0, radius);
      sphere_vertex(la0, lo1, radius);
      sphere_vertex(la1, lo1, radius);
      sphere_vertex(la0, lo0, radius);
      sphere_vertex(la1, lo1, radius);
      sphere_vertex(la1, lo0, radius);
    }
  }
  glEnd();
  glEndList();
}

