  g_stat.frame_start = t0;
  glClear(mask);
  g_stat.clear_us += now_us() - t0;
}

static void report_frame_stats(int64_t now) {
  char b[200];
  double n = (double)g_stat.frames;
  snprintf(b, sizeof b,
           "GL frames=%ld verts/frame=%.0f tris/frame=%.0f clear=%.1fms "
