           g_stat.gl_us / 1000.0 / n);
  spike_log(b);
  g_stat.window_start = now;
  g_stat.frames = 0;
  g_stat.clear_us = g_stat.gl_us = 0;
  g_stat.verts0 = spike_verts;
  g_stat.tris0 = spike_tris;
}

void glXSwapBuffers(Display *dpy, GLXDrawable drawable) {
  int64_t now = now_us();
